import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

const Register = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({ fullName: '', email: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const res = await axios.post('http://localhost:5000/api/auth/register', formData);
      localStorage.setItem('vrx_token', res.data.token);
      localStorage.setItem('vrx_user', JSON.stringify(res.data.user));
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.error || 'Registration failed');
    }
    setLoading(false);
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'linear-gradient(135deg, #F8FAFC 0%, #E2E8F0 100%)' }}>
      <div className="bg-white p-5 rounded-4 shadow" style={{ width: '100%', maxWidth: '450px' }}>
        <div className="text-center mb-4">
          <Link to="/" style={{ textDecoration: 'none', color: 'var(--dark)' }}>
            <img src="/assets/igntu_logo.png" alt="IGNTU Emblem" className="mb-3" style={{ height: '75px' }} />
            <h3 className="fw-bold m-0" style={{ color: 'var(--primary)' }}>VehicleRentx</h3>
          </Link>
          <h5 className="mt-3 text-muted">Create Account</h5>
          <p className="text-muted small">Start riding smarter today. Get ₹500 free credits!</p>
        </div>
        {error && <div className="alert alert-danger py-2 small">{error}</div>}
        <form onSubmit={handleRegister}>
          <div className="mb-3">
            <label className="form-label fw-bold small text-muted">FULL NAME</label>
            <input type="text" name="fullName" required className="form-control p-3 bg-light border-0 rounded-3" placeholder="John Doe" onChange={handleChange} />
          </div>
          <div className="mb-3">
            <label className="form-label fw-bold small text-muted">EMAIL ADDRESS</label>
            <input type="email" name="email" required className="form-control p-3 bg-light border-0 rounded-3" placeholder="username@igntu.ac.in" onChange={handleChange} />
          </div>
          <div className="mb-4">
            <label className="form-label fw-bold small text-muted">PASSWORD</label>
            <input type="password" name="password" required className="form-control p-3 bg-light border-0 rounded-3" placeholder="Create a strong password" onChange={handleChange} />
          </div>
          <button type="submit" className="btn btn-primary-custom w-100 py-3" disabled={loading}>
            {loading ? <><i className="fa-solid fa-spinner fa-spin me-2"></i>Creating account...</> : 'Sign Up'}
          </button>
        </form>
        <div className="text-center mt-4 text-muted">
          Already have an account? <Link to="/login" className="fw-bold text-primary">Log in</Link>
        </div>
      </div>
    </div>
  );
};

export default Register;
